SELECT
	CURVE_CODE
FROM
	MOD_CURVE_MAPPING


		and CURVE_GROUP_CODE = #{curveGroupCode}


		AND CURVE_TYPE = #{curveType}


		AND GRADE_RESULT = #{graderesult}

mapper.delete:
delete from MST_BOND_VALUATION_INFO where

	(
	SEC_ID = #{item.secId,jdbcType=VARCHAR}
	and VALUE_DATE = #{item.valueDate,jdbcType=DATE}
	and VALUE_SOURCE = #{item.valueSource,jdbcType=VARCHAR}
	)

delete from fin_product_valuation where

	(
		FINPROD_ID = #{item.finprodId,jdbcType=VARCHAR}
		and VAL_DATE = #{item.valDate,jdbcType=DATE}
	)
